import {backend} from './backend.js';
let current=null,ui,loading=false,playbackVersion=0;
export function initAudio(callbacks){ui=callbacks;const player=document.querySelector('#audio-player');if(!document.querySelector('#audio-close'))player.insertAdjacentHTML('beforeend','<button id="audio-close" class="btn" type="button" aria-label="Stop recording and close player" style="flex-shrink:0;align-self:center">Close ×</button>');document.querySelector('#audio-close').onclick=stopAudio;const audio=document.querySelector('#recording-audio');audio.addEventListener('play',updateButtons);audio.addEventListener('pause',updateButtons);audio.addEventListener('ended',updateButtons);audio.addEventListener('error',()=>ui.toast('The recording could not play. Try Play again to refresh its link.'));}
export function isAudioRecording(record){return record.storage_bucket==='lexamah-audio'&&record.storage_path&&String(record.mime_type||'').startsWith('audio/');}
function updateButtons(){const audio=document.querySelector('#recording-audio');document.querySelectorAll('[data-play-recording]').forEach(button=>{const active=button.dataset.playRecording===current?.id&&!audio.paused;button.textContent=active?'Pause':'▶ Play';button.setAttribute('aria-pressed',String(active));});}
export function syncAudioButtons(){if(ui)updateButtons();}
export function stopAudio(){playbackVersion++;const audio=document.querySelector('#recording-audio');audio.pause();audio.removeAttribute('src');audio.load();current=null;document.querySelector('#audio-player').classList.add('hidden');updateButtons();}
export async function playRecording(record){if(loading)return;if(!isAudioRecording(record))throw new Error('This is not an uploaded audio recording.');const audio=document.querySelector('#recording-audio');if(current?.id===record.id&&audio.src&&!audio.error){if(audio.paused)await audio.play();else audio.pause();return;}loading=true;const ticket=++playbackVersion;try{const url=await backend.fileURL(record.storage_path,'lexamah-audio');if(ticket!==playbackVersion)return;audio.pause();audio.src=url;current=record;document.querySelector('#audio-title').textContent=record.title;document.querySelector('#audio-subject').textContent=record.subject;document.querySelector('#audio-player').classList.remove('hidden');await audio.play();updateButtons();}catch(err){if(ticket===playbackVersion)throw err;}finally{loading=false;}}
